@DataProvider(name = "longs")
    public static Object[][] longsDataProvider() {
        List<Object[]> data = new ArrayList<>();

        // Function to create a stream using a RandomBoxedSpliterator

        Function<Function<SplittableRandom, Long>, LongStream> rbsf =
                sf -> StreamSupport.stream(new RandomBoxedSpliterator<>(new SplittableRandom(), 0, SIZE, sf), false).
                        mapToLong(i -> i);

        // Unbounded

        data.add(new Object[]{
                TestData.Factory.ofLongSupplier(
                        String.format("new SplittableRandom().longs().limit(%d)", SIZE),
                        () -> new SplittableRandom().longs().limit(SIZE)),
                randomAsserter(SIZE, Long.MAX_VALUE, 0L)
        });

        data.add(new Object[]{
                TestData.Factory.ofLongSupplier(
                        String.format("new SplittableRandom().longs(%d)", SIZE),
                        () -> new SplittableRandom().longs(SIZE)),
                randomAsserter(SIZE, Long.MAX_VALUE, 0L)
        });

        data.add(new Object[]{
                TestData.Factory.ofLongSupplier(
                        String.format("new RandomBoxedSpliterator(0, %d, sr -> sr.nextLong())", SIZE),
                        () -> rbsf.apply(sr -> sr.nextLong())),
                randomAsserter(SIZE, Long.MAX_VALUE, 0L)
        });

        // Bounded

        for (int b : BOUNDS) {
            for (int o : ORIGINS) {
                final long origin = o;
                final long bound = b;

                data.add(new Object[]{
                        TestData.Factory.ofLongSupplier(
                                String.format("new SplittableRandom().longs(%d, %d).limit(%d)", origin, bound, SIZE),
                                () -> new SplittableRandom().longs(origin, bound).limit(SIZE)),
                        randomAsserter(SIZE, origin, bound)
                });

                data.add(new Object[]{
                        TestData.Factory.ofLongSupplier(
                                String.format("new SplittableRandom().longs(%d, %d, %d)", SIZE, origin, bound),
                                () -> new SplittableRandom().longs(SIZE, origin, bound)),
                        randomAsserter(SIZE, origin, bound)
                });

                if (origin == 0) {
                    data.add(new Object[]{
                            TestData.Factory.ofLongSupplier(
                                    String.format("new RandomBoxedSpliterator(0, %d, sr -> sr.nextLong(%d))", SIZE, bound),
                                    () -> rbsf.apply(sr -> sr.nextLong(bound))),
                            randomAsserter(SIZE, origin, bound)
                    });
                }

                data.add(new Object[]{
                        TestData.Factory.ofLongSupplier(
                                String.format("new RandomBoxedSpliterator(0, %d, sr -> sr.nextLong(%d, %d))", SIZE, origin, bound),
                                () -> rbsf.apply(sr -> sr.nextLong(origin, bound))),
                        randomAsserter(SIZE, origin, bound)
                });
            }
        }

        return data.toArray(new Object[0][]);
    }

@DataProvider(name = "collections")
    public Object[][] createCollections() {
        List<Integer> content = LambdaTestHelpers.countTo(10);

        List<Collection<Integer>> collections = new ArrayList<>();
        collections.add(new ArrayList<>(content));
        collections.add(new LinkedList<>(content));
        collections.add(new Vector<>(content));

        collections.add(new HashSet<>(content));
        collections.add(new LinkedHashSet<>(content));
        collections.add(new TreeSet<>(content));

        Stack<Integer> stack = new Stack<>();
        stack.addAll(content);
        collections.add(stack);
        collections.add(new PriorityQueue<>(content));
        collections.add(new ArrayDeque<>(content));

        // Concurrent collections

        collections.add(new ConcurrentSkipListSet<>(content));

        ArrayBlockingQueue<Integer> arrayBlockingQueue = new ArrayBlockingQueue<>(content.size());
        for (Integer i : content)
            arrayBlockingQueue.add(i);
        collections.add(arrayBlockingQueue);
        collections.add(new PriorityBlockingQueue<>(content));
        collections.add(new LinkedBlockingQueue<>(content));
        collections.add(new LinkedTransferQueue<>(content));
        collections.add(new ConcurrentLinkedQueue<>(content));
        collections.add(new LinkedBlockingDeque<>(content));
        collections.add(new ConcurrentLinkedDeque<>(content));

        Object[][] params = new Object[collections.size()][];
        for (int i = 0; i < collections.size(); i++) {
            params[i] = new Object[]{collections.get(i).getClass().getName(), collections.get(i)};
        }

        return params;
    }

