                    for (int i = 0; i < NUM_TABLE_ROWS; i++)
                        stmt.executeUpdate("INSERT INTO " + AbstractSQLGenerator.escapeIdentifier(tableName)
                                + " (col1, col2) VALUES (" + i + ", '" + TEST_STRING + "')");
                }
                con.commit();
            }
        }

