@After
    public void cleanup() {
        try {
            assertThat("Logged exceptions", loggedExceptions, is(empty()));
            executor.shutdownNow();
            for (CompletableFuture<?> f : waitingFutures) {
                f.complete(null);
            }
        } finally {
            loggedExceptions.clear();
            waitingFutures.clear();
            waitUntil(5, SECONDS, executor::isTerminated);
        }
    }

